package com.bananalab.lite;
import android.app.*;import android.os.*;import android.content.*;import java.util.*;import java.io.*;import org.json.*;
public final class Stage50Instrumentation extends Instrumentation{
 void check(boolean b,String s){if(!b)throw new AssertionError(s);}void note(String s){Bundle b=new Bundle();b.putString("stream",s+"\n");sendStatus(0,b);}
 @Override public void onCreate(Bundle b){super.onCreate(b);start();}
 BananaEngine.Result run(Context c,Semilla m,String q)throws Exception{return BananaEngine.run(c,q,new ArrayList<String[]>(),"",true,m);}
 @Override public void onStart(){Bundle out=new Bundle();try{Context c=getTargetContext();JavaProject.prefs(c).edit().clear().commit();JavaEditModel.prefs(c).edit().clear().commit();Semilla model=OwnBrain.load(c);String scene=MobilePlan.snapshot(c),installed=JavaMethodEditor.prefs(c).getString("active","");BananaEngine.Result r=run(c,model,"prepara proyecto java");check(r.text.contains("Copia Java"),"project initialized");r=run(c,model,"compila proyecto java");check(r.text.contains("Compilación completa aprobada"),"all installed Java sources compile on Android: "+r.text);run(c,model,"guarda version proyecto java");note("NATIVE_COMPLETE_JAVA_PROJECT_BASELINE_COMPILES_OK");
  r=run(c,model,"entrena especialista java");check(r.text.contains("Entrené desde cero"),"own MLP trained on device: "+r.text);JavaEditModel trained=JavaEditModel.current(c);check(trained.trainCorrect>=34&&trained.testCorrect>=8,"own training/development evaluation");note("NATIVE_MLP_METRICS base="+trained.trainCorrect+"/36 dev="+trained.testCorrect+"/12 final="+trained.finalCorrect+"/12");
  String original=JavaProject.source(c,"SceneTiming.java");r=run(c,model,"edita metodo java SceneTiming.java#seconds: return frames(d)+(float)VideoExporter.FPS;");check(r.text.contains("Copia de SceneTiming.java#seconds editada"),"method outside chat edited");r=run(c,model,"propone cambio java SceneTiming.java#seconds: segundos dividiendo cuadros por cuadros por segundo");check(r.text.contains("DESPUÉS:")&&JavaProject.source(c,"SceneTiming.java").contains(" / "),"trained network generates operator change in actual existing project method");r=run(c,model,"compila proyecto java");check(r.text.contains("Compilación completa aprobada"),"neural proposal passes whole-project Java compilation: "+r.text);run(c,model,"guarda version proyecto java");note("NATIVE_OWN_MODEL_EDITS_REAL_NONCHAT_METHOD_AND_PROJECT_COMPILES_OK");
  run(c,model,"escribe archivo java NuevoCalculo.java: package com.bananalab.lite; final class NuevoCalculo { static int resultado(int x){ return AuxiliarCalculo.doble(x); } }");run(c,model,"escribe archivo java AuxiliarCalculo.java: package com.bananalab.lite; final class AuxiliarCalculo { static int doble(int x){ return x*2; } }");r=run(c,model,"compila proyecto java");check(r.text.contains("Compilación completa aprobada"),"new methods and dependent classes compile together: "+r.text);run(c,model,"guarda version proyecto java");r=run(c,model,"edita metodo java AuxiliarCalculo.java#doble: return faltaSimbolo;");check(run(c,model,"guarda version proyecto java").text.contains("Compilá"),"stale compile evidence rejected");r=run(c,model,"compila proyecto java");check(r.text.contains("no compila"),"actual arbitrary Java compiler error reported");run(c,model,"descarta cambios proyecto java");check(JavaProject.source(c,"AuxiliarCalculo.java").contains("return x*2"),"discard recovers accepted file");run(c,model,"deshace version proyecto java");check(!JavaProject.files(c,JavaProject.working(c)).containsKey("NuevoCalculo.java"),"multi-file source version recovered");check(scene.equals(MobilePlan.snapshot(c))&&installed.equals(JavaMethodEditor.prefs(c).getString("active","")),"general sources never executed or hot activated");note("NATIVE_MULTI_FILE_WORKSPACE_ERROR_GUARD_AND_RECOVERY_OK");out.putString("stream","PASS STAGE50 Android own-model training, frozen phrase evaluation, whole-project Java compilation, non-chat method generation, dependent class editing, compiler diagnostics, version guards and no arbitrary workspace execution.\n");finish(Activity.RESULT_OK,out);}catch(Throwable e){StringWriter s=new StringWriter();e.printStackTrace(new PrintWriter(s));out.putString("stream","FAIL "+s);finish(Activity.RESULT_CANCELED,out);}}
}
